#!/usr/bin/env python3
"""Frozen acceptance contract for ``review_trigger.py decide --explain-json``.

These tests freeze the machine-readable explained-verdict contract of the
review trigger (item ``review-trigger-explain-verdict``) before it is
implemented. They exercise only the external CLI against hermetic fixture
payloads, so the implementation may be structured any way that satisfies
them. Stdlib only, offline.

Frozen contract
===============

``--explain-json PATH`` is opt-in. With it, a decided run keeps stdout to
exactly one ``request|skip <reason>`` line (byte-identical to the run
without the flag) and writes exactly one JSON object to ``PATH`` (nothing
appended, no second document) with exactly these keys:

- ``schema``: the string ``"review-trigger-verdict.v1"``
- ``action``: ``"request"`` or ``"skip"``, equal to the printed action
- ``reason``: the printed reason text (stdout after the action word)
- ``reason_code``: the stable decider slug — ``draft``,
  ``already-reviewed``, ``ci-ok-red``, ``release-please``, ``risky``,
  ``checklist-incomplete``, ``audit-sample`` or ``ready-head``
- ``evaluated``: one entry per precedence rule, in precedence order, each
  with exactly the keys ``rule`` (the slug), ``matched`` (bool) and
  ``refs`` (list of deciding-input reference strings). Exactly one entry
  is matched, and its rule equals ``reason_code``.
- ``inputs``: the decision-input echo, with exactly the keys
  ``head_sha_short`` (first 12 hex chars), ``is_draft`` (bool),
  ``ci_ok_green`` (bool), ``checklist_complete`` (bool),
  ``checklist_missing`` (list of stable checklist phrases),
  ``risky`` (bool) and ``risk_categories`` (subset of
  ``risky-paths``, ``risk-labels``, ``large-diff``). Decision inputs
  only: never full check-run bodies or PR bodies.
- ``next_action``: bounded operator guidance (at most 300 chars),
  non-empty for every ``skip`` code.

Malformed input keeps exit 2 with a stable refusal taxonomy on stderr
(``not-json`` when stdin is not JSON, ``not-object`` when it is not a
JSON object); no sidecar is written on refusal. The precedence table is
explained, never changed.

Do not edit this file to make an implementation pass; change the
implementation instead.

Run: python3 -B -m unittest discover -s .github/scripts \\
    -p 'test_review_trigger_explain_acceptance.py' -v
"""

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

import review_trigger as rt
from test_review_trigger import FULL_BODY, IN_SAMPLE_SHA, OUT_OF_SAMPLE_SHA

SCRIPT = Path(__file__).with_name("review_trigger.py")

SCHEMA = "review-trigger-verdict.v1"

# Precedence order of review_trigger.decide(): first match wins.
RULE_ORDER = [
    "draft",
    "already-reviewed",
    "ci-ok-red",
    "release-please",
    "risky",
    "checklist-incomplete",
    "audit-sample",
    "ready-head",
]

RISK_CATEGORIES = frozenset({"risky-paths", "risk-labels", "large-diff"})

TOP_LEVEL_KEYS = frozenset(
    {
        "schema",
        "action",
        "reason",
        "reason_code",
        "evaluated",
        "inputs",
        "next_action",
    }
)
EVALUATED_KEYS = frozenset({"rule", "matched", "refs"})
INPUTS_KEYS = frozenset(
    {
        "head_sha_short",
        "is_draft",
        "ci_ok_green",
        "checklist_complete",
        "checklist_missing",
        "risky",
        "risk_categories",
    }
)

MAX_SIDECAR_BYTES = 8192
MAX_NEXT_ACTION = 300


def base_payload(**overrides):
    payload = {
        "is_draft": False,
        "ci_ok_green": True,
        "head_sha": OUT_OF_SAMPLE_SHA,
        "head_ref": "case_1cab5f7f-some-work",
        "author": "togetherweown[bot]",
        "body": FULL_BODY,
        "changed_files": ["docs/notes.md"],
        "labels": [],
        "additions": 10,
        "deletions": 5,
        "check_runs": [],
    }
    payload.update(overrides)
    return payload


def reviewed_runs(head_sha, conclusion="success"):
    return [
        {
            "name": "Paperclip Review",
            "status": "completed",
            "conclusion": conclusion,
            "head_sha": head_sha,
        }
    ]


INCOMPLETE_BODY = FULL_BODY.replace(
    "- [x] I updated the documentation this change touches",
    "- [ ] I updated the documentation this change touches",
)


def run_cli(args, stdin_text):
    return subprocess.run(
        [sys.executable, str(SCRIPT)] + args,
        input=stdin_text,
        capture_output=True,
        text=True,
        timeout=30,
    )


def run_decide(payload, *extra_args):
    return run_cli(["decide"] + list(extra_args), json.dumps(payload))


def read_single_object(raw_text):
    """Parse exactly one JSON document; fail on trailing content."""
    decoder = json.JSONDecoder()
    value, end = decoder.raw_decode(raw_text)
    if raw_text[end:].strip():
        raise AssertionError("sidecar holds more than one JSON document")
    return value


class ExplainAcceptance(unittest.TestCase):
    maxDiff = 4000

    def run_with_sidecar(self, payload):
        """Run decide --explain-json; return (proc, sidecar|None, raw|None)."""
        tmpdir = tempfile.TemporaryDirectory()
        self.addCleanup(tmpdir.cleanup)
        sidecar = Path(tmpdir.name) / "verdict.json"
        proc = run_decide(payload, "--explain-json", str(sidecar))
        if not sidecar.exists():
            return proc, None, None
        raw = sidecar.read_text(encoding="utf-8")
        return proc, read_single_object(raw), raw

    def assertStdoutVerdict(self, proc, payload):
        """Stdout stays one `action reason` line equal to decide()."""
        self.assertEqual(proc.returncode, 0)
        action, reason = rt.decide(payload)
        self.assertEqual(proc.stdout, "%s %s\n" % (action, reason))

    def assertValidSidecar(self, proc, sidecar, raw, payload, reason_code):
        self.assertIsNotNone(sidecar, "no sidecar written: %r" % proc.stderr)
        self.assertIsInstance(sidecar, dict)
        self.assertEqual(set(sidecar), TOP_LEVEL_KEYS)
        self.assertEqual(sidecar["schema"], SCHEMA)

        action, reason = rt.decide(payload)
        self.assertEqual(proc.stdout, "%s %s\n" % (action, reason))
        self.assertEqual(sidecar["action"], action)
        self.assertEqual(sidecar["reason"], reason)
        self.assertEqual(sidecar["reason_code"], reason_code)

        evaluated = sidecar["evaluated"]
        self.assertIsInstance(evaluated, list)
        self.assertEqual([e["rule"] for e in evaluated], RULE_ORDER)
        for entry in evaluated:
            self.assertEqual(set(entry), EVALUATED_KEYS)
            self.assertIsInstance(entry["matched"], bool)
            self.assertIsInstance(entry["refs"], list)
            for ref in entry["refs"]:
                self.assertIsInstance(ref, str)
                self.assertTrue(ref)
        matched = [e for e in evaluated if e["matched"]]
        self.assertEqual(len(matched), 1)
        self.assertEqual(matched[0]["rule"], reason_code)
        self.assertTrue(matched[0]["refs"], "decider names no input refs")

        inputs = sidecar["inputs"]
        self.assertEqual(set(inputs), INPUTS_KEYS)
        head_sha = payload.get("head_sha") or ""
        self.assertEqual(inputs["head_sha_short"], head_sha[:12])
        self.assertEqual(inputs["is_draft"], bool(payload.get("is_draft")))
        self.assertEqual(inputs["ci_ok_green"], bool(payload.get("ci_ok_green")))
        complete, missing = rt.checklist_status(payload.get("body") or "")
        self.assertEqual(inputs["checklist_complete"], complete)
        self.assertEqual(inputs["checklist_missing"], missing)
        for item in inputs["checklist_missing"]:
            self.assertIn(item, rt.CHECKLIST_ITEMS)
        risky, _ = rt.is_risky(
            payload.get("changed_files"),
            payload.get("labels"),
            payload.get("additions", 0),
            payload.get("deletions", 0),
        )
        self.assertEqual(inputs["risky"], risky)
        self.assertIsInstance(inputs["risk_categories"], list)
        self.assertEqual(inputs["risk_categories"], sorted(inputs["risk_categories"]))
        for category in inputs["risk_categories"]:
            self.assertIn(category, RISK_CATEGORIES)
        self.assertEqual(bool(inputs["risk_categories"]), risky)

        next_action = sidecar["next_action"]
        self.assertIsInstance(next_action, str)
        self.assertLessEqual(len(next_action), MAX_NEXT_ACTION)
        if action == "skip":
            self.assertTrue(next_action.strip())
        self.assertLessEqual(len(raw.encode("utf-8")), MAX_SIDECAR_BYTES)
        return sidecar

    def assertDecider(self, payload, reason_code):
        proc, sidecar, raw = self.run_with_sidecar(payload)
        self.assertStdoutVerdict(proc, payload)
        return self.assertValidSidecar(proc, sidecar, raw, payload, reason_code)

    # Full precedence matrix: each rule as the decider.

    def test_draft_decider(self):
        self.assertDecider(base_payload(is_draft=True), "draft")

    def test_already_reviewed_decider(self):
        self.assertDecider(
            base_payload(check_runs=reviewed_runs(OUT_OF_SAMPLE_SHA)),
            "already-reviewed",
        )

    def test_ci_ok_red_decider(self):
        self.assertDecider(base_payload(ci_ok_green=False), "ci-ok-red")

    def test_release_please_decider_by_author(self):
        sidecar = self.assertDecider(
            base_payload(author="github-actions[bot]", body="no checklist here"),
            "release-please",
        )
        self.assertFalse(sidecar["inputs"]["checklist_complete"])

    def test_release_please_decider_by_branch(self):
        self.assertDecider(
            base_payload(head_ref="release-please--branches--main", body=""),
            "release-please",
        )

    def test_risky_decider_by_path(self):
        sidecar = self.assertDecider(
            base_payload(changed_files=["ops/provisioner.sh"], body=""),
            "risky",
        )
        self.assertIn("risky-paths", sidecar["inputs"]["risk_categories"])

    def test_risky_decider_by_label(self):
        sidecar = self.assertDecider(
            base_payload(labels=["security"], body=""), "risky"
        )
        self.assertIn("risk-labels", sidecar["inputs"]["risk_categories"])

    def test_risky_decider_by_large_diff(self):
        sidecar = self.assertDecider(
            base_payload(body="", additions=500, deletions=200), "risky"
        )
        self.assertIn("large-diff", sidecar["inputs"]["risk_categories"])

    def test_checklist_incomplete_decider(self):
        sidecar = self.assertDecider(
            base_payload(body=INCOMPLETE_BODY), "checklist-incomplete"
        )
        self.assertEqual(
            sidecar["inputs"]["checklist_missing"], ["updated the documentation"]
        )

    def test_audit_sample_decider(self):
        self.assertDecider(base_payload(head_sha=IN_SAMPLE_SHA), "audit-sample")

    def test_ready_head_decider(self):
        self.assertDecider(base_payload(), "ready-head")

    # Cross-cutting contract properties.

    def test_skip_codes_carry_distinct_next_actions(self):
        payloads = {
            "draft": base_payload(is_draft=True),
            "already-reviewed": base_payload(
                check_runs=reviewed_runs(OUT_OF_SAMPLE_SHA)
            ),
            "ci-ok-red": base_payload(ci_ok_green=False),
            "checklist-incomplete": base_payload(body=INCOMPLETE_BODY),
        }
        actions = {}
        for code, payload in payloads.items():
            sidecar = self.assertDecider(payload, code)
            self.assertEqual(sidecar["action"], "skip")
            actions[code] = sidecar["next_action"]
        self.assertEqual(len(set(actions.values())), len(actions), actions)

    def test_sidecar_is_deterministic_across_runs(self):
        payload = base_payload()
        with tempfile.TemporaryDirectory() as tmpdir:
            sidecar = str(Path(tmpdir) / "verdict.json")
            first = run_decide(payload, "--explain-json", sidecar)
            self.assertEqual(first.returncode, 0, first.stderr)
            raw_first = Path(sidecar).read_text(encoding="utf-8")
            second = run_decide(payload, "--explain-json", sidecar)
            self.assertEqual(second.returncode, 0, second.stderr)
            raw_second = Path(sidecar).read_text(encoding="utf-8")
        self.assertEqual(read_single_object(raw_first), read_single_object(raw_second))

    def test_sidecar_overwrites_instead_of_appending(self):
        payload = base_payload()
        with tempfile.TemporaryDirectory() as tmpdir:
            sidecar = Path(tmpdir) / "verdict.json"
            sidecar.write_text("SENTINEL-NOT-JSON", encoding="utf-8")
            proc = run_decide(payload, "--explain-json", str(sidecar))
            self.assertEqual(proc.returncode, 0, proc.stderr)
            raw = sidecar.read_text(encoding="utf-8")
        self.assertNotIn("SENTINEL-NOT-JSON", raw)
        self.assertEqual(read_single_object(raw)["schema"], SCHEMA)

    def test_stdout_parity_with_and_without_flag(self):
        for payload in (
            base_payload(),
            base_payload(is_draft=True),
            base_payload(head_sha=IN_SAMPLE_SHA),
        ):
            with self.subTest(payload=rt.decide(payload)):
                with tempfile.TemporaryDirectory() as tmpdir:
                    sidecar = str(Path(tmpdir) / "verdict.json")
                    flagged = run_decide(payload, "--explain-json", sidecar)
                plain = run_decide(payload)
                self.assertEqual(flagged.returncode, plain.returncode)
                self.assertEqual(flagged.stdout, plain.stdout)
                self.assertEqual(flagged.stderr, plain.stderr)

    def test_bounded_output_echoes_no_bodies(self):
        check_blob = "CR-BLOB-" + "A" * 8000
        body_blob = "BODY-BLOB-" + "B" * 8000
        runs = [
            {
                "name": "ci-ok",
                "status": "completed",
                "conclusion": "success",
                "head_sha": OUT_OF_SAMPLE_SHA,
                "output": {"title": "log", "summary": check_blob},
            }
        ]
        payload = base_payload(
            body=FULL_BODY + "\n" + body_blob + "\n",
            check_runs=runs,
        )
        proc, sidecar, raw = self.run_with_sidecar(payload)
        self.assertStdoutVerdict(proc, payload)
        self.assertValidSidecar(proc, sidecar, raw, payload, "ready-head")
        self.assertNotIn(check_blob, raw)
        self.assertNotIn("CR-BLOB-", raw)
        self.assertNotIn(body_blob, raw)
        self.assertNotIn("BODY-BLOB-", raw)
        self.assertNotIn("CR-BLOB-", proc.stdout)
        self.assertNotIn("BODY-BLOB-", proc.stdout)

    # Refusal taxonomy: exit 2, stable code on stderr, no sidecar.

    def test_not_json_refusal_writes_no_sidecar(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            sidecar = Path(tmpdir) / "verdict.json"
            proc = run_cli(
                ["decide", "--explain-json", str(sidecar)], "{not json"
            )
            self.assertEqual(proc.returncode, 2)
            self.assertEqual(proc.stdout, "")
            self.assertIn("not-json", proc.stderr)
            self.assertFalse(sidecar.exists())

    def test_not_object_refusal_writes_no_sidecar(self):
        for raw_input in ("[1, 2]", '"just a string"', "42", "null"):
            with self.subTest(stdin=raw_input):
                with tempfile.TemporaryDirectory() as tmpdir:
                    sidecar = Path(tmpdir) / "verdict.json"
                    proc = run_cli(
                        ["decide", "--explain-json", str(sidecar)], raw_input
                    )
                    self.assertEqual(proc.returncode, 2)
                    self.assertEqual(proc.stdout, "")
                    self.assertIn("not-object", proc.stderr)
                    self.assertFalse(sidecar.exists())

    def test_refusal_taxonomy_without_flag(self):
        proc = run_cli(["decide"], "{not json")
        self.assertEqual(proc.returncode, 2)
        self.assertIn("not-json", proc.stderr)
        proc = run_cli(["decide"], "[1, 2]")
        self.assertEqual(proc.returncode, 2)
        self.assertIn("not-object", proc.stderr)

    # CLI shape: the flag is known, documented, and fail-closed.

    def test_usage_mentions_explain_json(self):
        proc = run_cli([], "")
        self.assertEqual(proc.returncode, 2)
        self.assertIn("explain-json", proc.stderr)

    def test_unknown_flag_is_refused(self):
        proc = run_decide(base_payload(), "--bogus", "x")
        self.assertEqual(proc.returncode, 2)
        self.assertEqual(proc.stdout, "")

    def test_missing_flag_value_is_refused(self):
        proc = run_decide(base_payload(), "--explain-json")
        self.assertEqual(proc.returncode, 2)
        self.assertEqual(proc.stdout, "")


if __name__ == "__main__":
    unittest.main()
